use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lt: Vec<int> = []
    let mut rt: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" || cmd == "contains" || cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            // find
            let mut cur = root
            let mut par: int = -1
            let mut went_left = false
            while cur != -1 && keys[cur as usize] != x {
                par = cur
                if x < keys[cur as usize] {
                    went_left = true
                    cur = lt[cur as usize]
                } else {
                    went_left = false
                    cur = rt[cur as usize]
                }
            }
            if cmd == "contains" {
                if cur != -1 { println("yes") } else { println("no") }
            } else if cmd == "insert" {
                if cur != -1 {
                    println("dup")
                } else {
                    let id = keys.len() as int
                    keys.push(x)
                    lt.push(-1)
                    rt.push(-1)
                    if par == -1 {
                        root = id
                    } else if went_left {
                        lt[par as usize] = id
                    } else {
                        rt[par as usize] = id
                    }
                    println("ok")
                }
            } else {
                if cur == -1 {
                    println("missing")
                } else {
                    let l = lt[cur as usize]
                    let r = rt[cur as usize]
                    if l != -1 && r != -1 {
                        let mut sp = cur
                        let mut s = r
                        while lt[s as usize] != -1 {
                            sp = s
                            s = lt[s as usize]
                        }
                        keys[cur as usize] = keys[s as usize]
                        let sr = rt[s as usize]
                        if sp == cur {
                            rt[sp as usize] = sr
                        } else {
                            lt[sp as usize] = sr
                        }
                    } else {
                        let child = if l != -1 { l } else { r }
                        if par == -1 {
                            root = child
                        } else if went_left {
                            lt[par as usize] = child
                        } else {
                            rt[par as usize] = child
                        }
                    }
                    println("ok")
                }
            }
        } else if cmd == "inorder" {
            let mut out = ""
            let mut stack: Vec<int> = []
            let mut cur = root
            while cur != -1 || stack.len() > 0 {
                while cur != -1 {
                    stack.push(cur)
                    cur = lt[cur as usize]
                }
                let n = stack.len()
                let node = stack[n - 1]
                stack.pop()
                if out != "" { out = out + " " }
                out = out + "${keys[node as usize]}"
                cur = rt[node as usize]
            }
            if out == "" { println("<empty>") } else { println("${out}") }
        } else if cmd == "height" {
            let mut best = 0
            let mut stack: Vec<int> = []
            let mut depth: Vec<int> = []
            if root != -1 {
                stack.push(root)
                depth.push(1)
            }
            while stack.len() > 0 {
                let n = stack.len()
                let node = stack[n - 1]
                let d = depth[n - 1]
                stack.pop()
                depth.pop()
                if d > best { best = d }
                if lt[node as usize] != -1 {
                    stack.push(lt[node as usize])
                    depth.push(d + 1)
                }
                if rt[node as usize] != -1 {
                    stack.push(rt[node as usize])
                    depth.push(d + 1)
                }
            }
            println("${best}")
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut c = root
                if cmd == "min" {
                    while lt[c as usize] != -1 { c = lt[c as usize] }
                } else {
                    while rt[c as usize] != -1 { c = rt[c as usize] }
                }
                println("${keys[c as usize]}")
            }
        }
    }
}

